Definition laframe (sp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 ra : word) (m1 : mem) (j8 : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -96)
    [CB 8 j8; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

